package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.util.Comparator;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.access.RoleRepository;
import net.officefloor.hq.app.access.SettingRepository;
import net.officefloor.hq.app.history.SheetHistory;
import net.officefloor.hq.app.history.TodaySnapshot;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Val;

/**
 * Once the sheet's today is set: with grace days on, closes every open period (neither closed nor soft-closed) whose to-date plus the grace days is
 * before the new today, in order of their to-dates, as a close by hand would — whoever set the today, the sheet's
 * close permission governs only a close by hand — each writing PERIOD_CLOSED with auto=yes. The snapshot taken as the
 * today moved on shows each such period closed.
 */
public class AutoClosePeriods {
    public void close(@Val SheetResponse sheet, @Val LocalDate today, @Val ChangedBy by, @Val TodaySnapshot snapshot,
            SheetHistory history, PeriodRepository repository,
            RoleRepository roles, SettingRepository settings, Rollup rollup, Audit audit) {
        Integer grace = settings.graceDays(sheet.id());
        if (grace == null) {
            return;
        }
        for (Period period : repository.list(sheet.id()).stream()
                .filter(p -> !p.closed() && !p.soft() && p.to().plusDays(grace).isBefore(today))
                .sorted(Comparator.comparing(Period::to).thenComparing(Period::id)).toList()) {
            Period closed = ClosePeriod.fix(period, repository, rollup);
            if (closed != null) {
                audit.record(RecordPeriodClosed.line(closed, by) + " auto=yes");
                if (snapshot != null && snapshot.id() != null) {
                    history.refreshPeriod(snapshot.id(), closed.id());
                }
            }
        }
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.access.RoleRepository;
import net.officefloor.hq.app.access.SettingRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Soft-closes the period (by a role the sheet's close permission gives), fixing its due-total and each person's as
 * they are now while claims dated inside it can still change; refuses a period already closed or soft-closed.
 */
public class SoftClosePeriod {
    public void softClose(@Val Period period, @Val ChangedBy by, PeriodRepository repository, RoleRepository roles,
            SettingRepository settings, Rollup rollup, Out<SoftClosedPeriod> softClosed) throws BadRequestException {
        String role = roles.roleOf(period.sheetId(), by.name());
        if (!settings.allows(period.sheetId(), "close", role)) {
            throw new BadRequestException("A " + role + " may not close a period on this sheet");
        }
        if (period.closed()) {
            throw new BadRequestException("That period is already closed");
        }
        if (period.soft()) {
            throw new BadRequestException("That period is already soft-closed");
        }
        Period fixed = ClosePeriod.softFix(period, repository, rollup);
        if (fixed == null) {
            throw new BadRequestException("The period was closed by someone else; reload the sheet");
        }
        softClosed.set(new SoftClosedPeriod(fixed));
    }
}

